/* Shared current/recorded Duty Form. Scoped so other editors and log graphs keep their contracts. */
html body .dd-root.driver-duty-form{position:fixed!important;inset:0!important;z-index:20001!important;display:flex!important;flex-direction:column!important;width:100%!important;max-width:none!important;height:100dvh!important;max-height:none!important;border:0!important;border-radius:0!important;padding:0!important;background:#f3f6f8!important;color:#172638!important;box-sizing:border-box;--driver-accent:#2455d9;--driver-accent-soft:#eef3ff;font-family:inherit;overflow:hidden!important}
html body .dd-root *{box-sizing:border-box}
html body .dd-root .dd-header{display:grid!important;grid-template-columns:48px minmax(0,1fr) 48px;align-items:center;flex:0 0 auto!important;gap:8px;background:#172638!important;color:white!important;margin:0!important;padding:calc(env(safe-area-inset-top,0px) + 8px) 12px 10px!important;min-height:68px;height:auto!important;position:relative!important;top:auto!important;border:0!important}
html body .dd-root .dd-header>div{display:block!important;text-align:center;line-height:1.25;min-width:0}
html body .dd-root .dd-header b{font-size:23px;font-weight:800}
html body .dd-root .dd-header small{display:block;font-size:12px;color:#d4dfed!important;white-space:normal;margin-top:4px}
html body .dd-root .dd-header button{height:44px;width:44px;padding:0;border:0;border-radius:12px;background:#ffffff16!important;color:white!important;font-size:28px;position:static!important}
html body .dd-root .dd-body{flex:1 1 auto!important;min-height:0;overflow-y:auto!important;overflow-x:hidden!important;display:flex!important;flex-direction:column!important;gap:14px!important;padding:14px 12px 18px!important;margin:0!important;background:#f3f6f8!important;-webkit-overflow-scrolling:touch}
html body .dd-root .dd-body>*{flex:0 0 auto;min-width:0}
html body .dd-root .dd-field,html body .dd-root .dd-body .picker-section,html body .dd-root .dd-body .form-section,html body .dd-root .dd-time-block{background:white!important;border:1px solid #d7e0e9!important;border-radius:16px!important;padding:14px!important;margin:0!important;min-width:0;box-shadow:none!important}
html body .dd-root .dd-selection{display:grid;gap:14px}
html body .dd-root .dd-field-head,html body .dd-root .picker-label-row{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 12px!important;color:#172638!important;min-width:0}
html body .dd-root .dd-field-head strong,html body .dd-root .picker-label-row label{font-size:14px!important;font-weight:800!important;letter-spacing:.02em}
html body .dd-root .dd-field-head span{font-size:12px;text-align:right;color:#596b82}
html body .dd-root .dd-status-grid{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:8px!important;background:transparent!important;padding:0!important;border:0!important}
html body .dd-root .dd-status-grid button{display:flex!important;flex-direction:column;justify-content:center;align-items:center;min-height:64px!important;height:auto!important;padding:9px 3px!important;background:#f4f7fb!important;color:#243b59!important;border:1px solid #d7e0e9!important;border-radius:12px!important;box-shadow:none!important}
html body .dd-root .dd-status-grid b{font-size:23px;font-weight:900}
html body .dd-root .dd-status-grid small{display:block!important;font-size:10px!important;line-height:1.2;letter-spacing:0!important;color:inherit!important;white-space:normal!important}
html body .dd-root .dd-activity-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px!important}
html body .dd-root .dd-activity-grid button{width:100%!important;min-height:48px!important;height:auto!important;padding:12px 8px!important;border:1px solid #cbd7e6!important;background:#f5f8fd!important;color:#172638!important;-webkit-text-fill-color:currentColor!important;border-radius:12px!important;font:inherit!important;font-size:14px!important;font-weight:750!important;line-height:1.25!important;white-space:normal!important;box-shadow:none!important}
html body .dd-root .dd-status-grid button[aria-pressed=true],html body .dd-root .dd-activity-grid button[aria-pressed=true]{background:#2455d9!important;border-color:#2455d9!important;color:white!important;-webkit-text-fill-color:white!important}
html body .dd-root .dd-fields{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important}
html body .dd-root .dd-fields label{display:grid;gap:6px;min-width:0;font-size:13px;color:#52647b;font-weight:700}
html body .dd-root input,html body .dd-root textarea{font-family:inherit;color:#172638!important;-webkit-text-fill-color:#172638!important;background:white!important;border:1px solid #c9d4e1;border-radius:10px;min-height:48px;max-width:100%;font-size:16px!important;line-height:1.4;padding:10px;box-shadow:none!important}
html body .dd-root input[readonly]{background:#f4f7fb!important}
html body .dd-root textarea{width:100%;min-height:88px;resize:vertical}
html body .dd-root .dd-location{display:grid!important;grid-template-columns:44px minmax(0,1fr) 36px!important;border:1px solid #c9d4e1!important;border-radius:12px!important;overflow:hidden;min-height:52px!important;background:white!important}
html body .dd-root .dd-location input{border:0!important;border-radius:0!important;min-width:0;width:100%!important;padding:10px!important}
html body .dd-root .dd-location button{background:white!important;color:#2455d9!important;border:0!important;min-width:0!important;width:100%!important;min-height:48px!important;padding:2px!important;font-size:24px}
html body .dd-root .dd-help,html body .dd-root .dd-recorded-context{font-size:12px!important;line-height:1.5;color:#52647b!important;margin:8px 0;white-space:normal}
html body .dd-root .dd-footer{position:relative!important;flex:0 0 auto!important;display:flex!important;gap:10px!important;align-items:center;inset:auto!important;width:100%!important;margin:0!important;background:white!important;border-top:1px solid #d7e0e9!important;padding:10px 12px calc(env(safe-area-inset-bottom,0px) + 10px)!important;min-height:72px!important;box-shadow:0 -2px 8px #15283c0c!important}
html body .dd-root .dd-footer button{position:static!important;min-height:50px!important;height:auto!important;width:auto!important;padding:12px!important;margin:0!important;border-radius:12px!important;font:inherit!important;font-weight:800!important;font-size:16px!important;box-shadow:none!important}
html body .dd-root .dd-footer .cancel-main{flex:0 0 88px;background:#edf2f8!important;color:#243b59!important;border:1px solid #d7e0e9!important}
html body .dd-root .dd-footer .save-main,html body .dd-root .dd-footer .status-save{flex:1 1 auto!important;background:#2455d9!important;color:white!important;border:1px solid #2455d9!important}
html body .dd-root .dd-footer button:disabled{opacity:.48!important}
html body .dd-root .dd-time-block{padding:8px!important}
html body .dd-root .dd-time-block .selected-duration-live{display:flex!important;gap:6px;flex-wrap:wrap;font-size:12px!important;padding:6px;color:#52647b!important}
html body .dd-root .dd-time-block .selected-duration-live b{color:#172638}
html body .dd-root .dd-time-block .selected-duration-live em{font-style:normal;flex-basis:100%}
html body .dd-root .dd-body .modern-quick-time-v11027,html body .dd-root .dd-body .modern-fine-time-v11027{position:static}
html body .dd-root .dd-conflict{padding:12px;margin-bottom:12px;background:#fff5df;border:1px solid #e7c578;border-radius:12px;color:#513d16;font-size:13px;line-height:1.5;overflow-wrap:anywhere}
html body .dd-root .dd-conflict button{min-height:44px;margin-top:8px;padding:10px;background:white;border:1px solid #b89654;border-radius:9px;color:#513d16;font-weight:700}
html body .dd-root button:focus-visible,html body .dd-root input:focus-visible{outline:3px solid #5798e6!important;outline-offset:2px}
@media(min-width:740px){html body .dd-root .dd-body{padding-left:max(16px,calc((100vw - 720px)/2))!important;padding-right:max(16px,calc((100vw - 720px)/2))!important}html body .dd-root .dd-header,html body .dd-root .dd-footer{padding-left:max(16px,calc((100vw - 720px)/2))!important;padding-right:max(16px,calc((100vw - 720px)/2))!important}}

html body .dd-root .dd-body .dd-time-block{margin:0 -12px!important;width:calc(100% + 24px);max-width:100vw;padding:0!important;border:0!important;border-radius:0!important;overflow:visible}
html body .dd-root .dd-time-block .modern-time-wrap-v11027{padding:10px 12px!important}
html body .dd-root .dd-footer .edit-sticky-save{position:static!important;display:flex!important;flex:1 1 auto!important;inset:auto!important;margin:0!important;padding:0!important;width:auto!important;background:transparent!important}
